import javafx.application.Platform;
import javafx.event.ActionEvent;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.control.*;
import javafx.scene.layout.BorderPane;
import javafx.util.StringConverter;
import timur.popov.financemanager.MainWindow;
import timur.popov.financemanager.UserSession;
import timur.popov.financemanager.controller.dialogs.LogInController;
import timur.popov.financemanager.controller.dialogs.QuickActionController;
import timur.popov.financemanager.dao.UserDAO;
import timur.popov.financemanager.model.User;

import java.io.IOException;
import java.util.List;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MainWindowController {
    @FXML
    public ComboBox<User> userSwitcherComboBox;
    @FXML
    private BorderPane mainBorderPane;

    /** Prevents re-entry when reverting the ComboBox selection after a failed login. */
    private boolean isReverting = false;
    /** Tracks the last successfully authenticated user. */
    private User lastLoggedInUser = null;

    @FXML
    public void initialize() {
        // Display user names in the combo box
        userSwitcherComboBox.setConverter(new StringConverter<User>() {
            @Override
            public String toString(User user) {
                return user != null ? user.getName() : "";
            }
            @Override
            public User fromString(String string) { return null; }
        });

        // Load users from the database
        List<User> users = UserDAO.getAllUsers();
        userSwitcherComboBox.getItems().setAll(users);

        // Pre-select the first user (no handler registered yet, so no login fires here)
        if (!users.isEmpty()) {
            userSwitcherComboBox.getSelectionModel().selectFirst();
        }

        // Guard user switching behind a login dialog
        userSwitcherComboBox.setOnAction(event -> {
            if (isReverting) return;
            User selected = userSwitcherComboBox.getValue();
            if (selected == null) return;
            // Skip if this is already the authenticated user
            if (lastLoggedInUser != null && selected.getUserId() == lastLoggedInUser.getUserId()) return;

            boolean success = showLoginDialog(selected);
            if (success) {
                lastLoggedInUser = selected;
                UserSession.setCurrentUser(selected);
            } else {
                // Revert to the previous user without triggering the handler again
                isReverting = true;
                userSwitcherComboBox.setValue(lastLoggedInUser);
                isReverting = false;
            }
        });

        // Show startup login after the stage is visible
        if (!users.isEmpty()) {
            User firstUser = users.get(0);
            Platform.runLater(() -> {
                boolean success = showLoginDialog(firstUser);
                if (success) {
                    lastLoggedInUser = firstUser;
                    UserSession.setCurrentUser(firstUser);
                } else {
                    // User cancelled login at startup — close the application
                    Platform.exit();
                }
            });
        }
    }

    public void SwitchSectionOnMainWindow(ActionEvent actionEvent) {
        Pattern pattern = Pattern.compile("id=(\\w+)");
        Matcher matcher = pattern.matcher(actionEvent.toString()); // Button[id=transactionsButton, styleClass=button]'Transactions'
        String result;
        try {
            if (matcher.find()) {
                result = matcher.group(1).replaceFirst("Button$", ""); // removes suffix Button at the end(Result: transactions)
            } else {
                throw new Exception("wrong name of Button");
            }

            FXMLLoader fxmlLoader = new FXMLLoader(MainWindow.class.getResource(String.format("view/%s.fxml", result)));
            mainBorderPane.setCenter(fxmlLoader.load());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }


    }
    @FXML
    private void handleManageUsers() {
        // Logic to open a "Manage Users" pop-up or new tab
        System.out.println("Manage Users clicked!");
    }

    @FXML
    private void handleSettings(ActionEvent actionEvent) {
        // Logic to open a "Settings" pop-up or new tab
        System.out.println(actionEvent.toString());
    }
    @FXML
    public void handleAddIncome(ActionEvent actionEvent) throws IOException {
        FXMLLoader fxmlLoader = new FXMLLoader(MainWindow.class.getResource("view/dialogs/add-income-dialog.fxml"));
        Dialog<QuickActionController.EnteredData> dialog = new Dialog<>();

        dialog.setDialogPane(fxmlLoader.load());
        dialog.setTitle("Add Income");

        QuickActionController controller = fxmlLoader.getController();

        // Provide result converter
        dialog.setResultConverter(dialogButton -> {
            if (dialogButton == ButtonType.APPLY) {
                return controller.buildResult();  // returns null if validation fails
            } else if (dialogButton == ButtonType.CLOSE) {
                return new QuickActionController.EnteredData(-1, null, null);
            }
            return null;
        });


        Optional<QuickActionController.EnteredData> result;
        do {
            result = dialog.showAndWait();
            // If validation failed, buildResult() returned null → dialog returns empty Optional
        } while (result.isEmpty()); // show dialog again until valid input
        // If valid data entered:
        QuickActionController.EnteredData data = result.get();

        if(data.amount() == -1) {
            dialog.close();
        }
        System.out.println("Amount: " + data.amount());
        System.out.println("Category: " + data.category());
        System.out.println("Description: " + data.description());
    }
    @FXML
    public void handleAddExpense(ActionEvent actionEvent) throws IOException { // ToDo: handle exceptions
        FXMLLoader fxmlLoader = new FXMLLoader(MainWindow.class.getResource("view/dialogs/add-expense-dialog.fxml"));
        Dialog<QuickActionController.EnteredData> dialog = new Dialog<>();

        dialog.setDialogPane(fxmlLoader.load());
        dialog.setTitle("Add Expanse");

        QuickActionController controller = fxmlLoader.getController();

        // Provide result converter
        dialog.setResultConverter(dialogButton -> {
            if (dialogButton == ButtonType.APPLY) {
                return controller.buildResult();  // returns null if validation fails
            } else if (dialogButton == ButtonType.CLOSE) {
                return new QuickActionController.EnteredData(-1, null, null);
            }
            return null;
        });


        Optional<QuickActionController.EnteredData> result;
        do {
            result = dialog.showAndWait();
            // If validation failed, buildResult() returned null → dialog returns empty Optional
        } while (result.isEmpty()); // show dialog again until valid input
        // If valid data entered:
        QuickActionController.EnteredData data = result.get();

        if(data.amount() == -1) {
            dialog.close();
        }
        System.out.println("Amount: " + data.amount());
        System.out.println("Category: " + data.category());
        System.out.println("Description: " + data.description());
    }

    /**
     * Shows the login dialog for the given user.
     * Returns true if login succeeded, false if the user cancelled.
     */
    private boolean showLoginDialog(User user) {
        try {
            FXMLLoader fxmlLoader = new FXMLLoader(MainWindow.class.getResource("view/dialogs/log-in-dialog.fxml"));
            Dialog<Boolean> dialog = new Dialog<>();
            dialog.setDialogPane(fxmlLoader.load());
            dialog.setTitle("Login");

            LogInController controller = fxmlLoader.getController();
            controller.setUser(user);   // populates greeting label and renames buttons

            dialog.setResultConverter(buttonType -> {
                if (buttonType == ButtonType.APPLY) {
                    return controller.buildResult(); // null on validation failure → re-show
                }
                return Boolean.FALSE; // CLOSE or window-X → cancel
            });

            Optional<Boolean> result;
            do {
                result = dialog.showAndWait();
            } while (result.isEmpty()); // empty means buildResult() returned null (validation failed)

            return result.get(); // TRUE = success, FALSE = cancelled
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public ComboBox<User> getUserSwitcherComboBox() {
        return userSwitcherComboBox;
    }

    //
//        Stage stage = new Stage();
//        stage.setWidth(300);
//        stage.setHeight(300);
//        stage.initModality(Modality.APPLICATION_MODAL);
//
//        stage.show();

}

package timur.popov.financemanager.model;

import java.util.Calendar;
import java.util.List;

public class User {
    private final int USER_ID;
    private String name;
    private Calendar creationDate;
    private String hashedPassword;
    private List<Account> accountList;

    public User(int USER_ID, String name, String creationDate, String hashedPassword, List<Account> accountList) {
        this.USER_ID = USER_ID;
        this.name = name;
        //this.creationDate = creationDate;
        this.hashedPassword = hashedPassword;
        this.accountList = accountList;
    }

    public int getUserId() {
        return USER_ID;
    }

    public String getName() {
        return name;
    }
}

package timur.popov.financemanager.model;

import java.util.Calendar;
import java.util.List;

public class User {
    private final int USER_ID;
    private String name;
    private Calendar creationDate;
    private String hashedPassword;
    private List<Account> accountList;

    public User(int USER_ID, String name, String creationDate, String hashedPassword, List<Account> accountList) {
        this.USER_ID = USER_ID;
        this.name = name;
        //this.creationDate = creationDate;
        this.hashedPassword = hashedPassword;
        this.accountList = accountList;
    }

    public int getUserId() {
        return USER_ID;
    }

    public String getName() {
        return name;
    }

    public String getPassword() {
        return hashedPassword;
    }
}
